cat >> public/activity.css <<'EOF'

/* Filters. Tokens come from the shared token sheet; size fallbacks are the
   values in docs/ui-guidelines/01-foundations.md until the sheet is linked. */
.activity-filters:not([hidden]) {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: var(--space-5, 0.75rem) var(--space-8, 1.5rem);
  margin-bottom: var(--space-5, 0.75rem);
}

.activity-filters__show {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-4, 0.5rem) var(--space-6, 1rem);
  margin: 0;
  padding: 0;
  border: 0;
}

.activity-filters legend,
.activity-filters__field label {
  margin-bottom: var(--space-4, 0.5rem);
  padding: 0;
  font-size: var(--type-label, 0.875rem);
  font-weight: 500;
}

.activity-filters__show label {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2, 0.25rem);
  min-height: var(--space-8, 1.5rem);
  font-size: var(--type-body, 0.9375rem);
}

.activity-filters__field {
  display: flex;
  flex-direction: column;
}

.activity-filters select {
  padding: var(--space-4, 0.5rem) var(--space-5, 0.75rem);
  font: inherit;
  font-size: var(--type-body, 0.9375rem);
  color: var(--text-primary);
  background: var(--surface-panel);
  border: var(--border-width-hairline) solid var(--border-default);
  border-radius: var(--radius-md);
}

.activity-filters select:hover {
  border-color: var(--border-strong);
}

.activity-filters button,
.activity-empty button {
  min-height: var(--space-8, 1.5rem);
  padding: var(--space-4, 0.5rem) var(--space-6, 1rem);
  font: inherit;
  font-size: var(--type-label, 0.875rem);
  border-radius: var(--radius-md);
}

.activity-filters button {
  color: var(--text-primary);
  background: var(--surface-panel);
  border: var(--border-width-hairline) solid var(--border-default);
}

.activity-filters button:hover {
  border-color: var(--border-strong);
}

.activity-empty button {
  color: var(--text-inverse);
  background: var(--accent-fill);
  border: var(--border-width-hairline) solid var(--accent-fill);
}

.activity-filters input:focus-visible,
.activity-filters select:focus-visible,
.activity-filters button:focus-visible,
.activity-empty button:focus-visible {
  outline: var(--border-width-thick) solid var(--border-focus);
  outline-offset: var(--space-1, 0.125rem);
}

.activity-filters select,
.activity-filters button {
  transition: border-color var(--duration-fast) var(--ease-standard);
}

@media (prefers-reduced-motion: reduce) {
  .activity-filters select,
  .activity-filters button {
    transition: none;
  }
}

.activity-count {
  margin: 0 0 var(--space-5, 0.75rem);
  font-size: var(--type-body-sm, 0.8125rem);
  color: var(--text-secondary);
}

.activity-empty {
  padding: var(--space-13) var(--space-6, 1rem);
  text-align: center;
  color: var(--text-secondary);
}

.activity-empty__title {
  margin: 0 0 var(--space-4, 0.5rem);
  font-size: var(--type-body, 0.9375rem);
  font-weight: 500;
}
EOF
