node --version; cat > /tmp/activity-check.mjs <<'EOF'
import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
const url = 'file://' + process.argv[2];
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  ['--headless=new', '--remote-debugging-port=9333', '--user-data-dir=/tmp/activity-chrome', '--lang=en-US', 'about:blank'], { stdio: 'ignore' });
await new Promise(r => setTimeout(r, 2000));
const targets = await (await fetch('http://127.0.0.1:9333/json')).json();
const ws = new WebSocket(targets.find(t => t.type === 'page').webSocketDebuggerUrl);
await new Promise(r => ws.onopen = r);
let id = 0; const pending = {}; const logs = [];
ws.onmessage = m => { const d = JSON.parse(m.data); if (d.id && pending[d.id]) pending[d.id](d); 
  if (d.method === 'Runtime.exceptionThrown') logs.push('EXCEPTION ' + JSON.stringify(d.params.exceptionDetails.exception?.description));
  if (d.method === 'Runtime.consoleAPICalled') logs.push('console ' + d.params.args.map(a => a.value).join(' ')); };
const send = (method, params = {}) => new Promise(r => { pending[++id] = r; ws.send(JSON.stringify({ id, method, params })); });
const ev = async expr => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result?.result?.value;
const wait = ms => new Promise(r => setTimeout(r, ms));
const state = () => ev(`JSON.stringify({count: document.getElementById('activity-count').textContent,
  visible: [...document.querySelectorAll('#activity-table tbody tr:not([hidden])')].map(r => r.cells[1].textContent).reduce((a,t)=>(a[t]=(a[t]||0)+1,a),{}),
  tableHidden: document.getElementById('activity-table').hidden, emptyHidden: document.getElementById('activity-empty').hidden,
  formHidden: document.getElementById('activity-filters').hidden, week: document.getElementById('activity-week').value,
  show: document.querySelector('input[name=show]:checked')?.value, focused: document.activeElement?.outerHTML.slice(0,80)})`);
async function clickEl(sel) {
  const box = JSON.parse(await ev(`(() => { const r = document.querySelector(${JSON.stringify(sel)}).getBoundingClientRect(); return JSON.stringify({x: r.x + r.width/2, y: r.y + r.height/2}); })()`));
  for (const type of ['mousePressed', 'mouseReleased']) await send('Input.dispatchMouseEvent', { type, x: box.x, y: box.y, button: 'left', clickCount: 1 });
  await wait(100);
}
async function key(k, code, keyCode) { for (const type of ['keyDown','keyUp']) await send('Input.dispatchKeyEvent', { type, key: k, code, windowsVirtualKeyCode: keyCode }); await wait(80); }
async function shot(name) { const r = await send('Page.captureScreenshot', { captureBeyondViewport: true }); writeFileSync(`/tmp/activity-${name}.png`, Buffer.from(r.result.data, 'base64')); }
await send('Runtime.enable'); await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1200, height: 900, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url }); await wait(800);
console.log('options', await ev(`[...document.querySelectorAll('#activity-week option')].map(o => o.textContent).join(' | ')`));
console.log('load', await state()); await shot('load');
await clickEl('input[value=failed]'); console.log('click Failed sign-ins', await state());
await clickEl('input[value=security]'); console.log('click Security changes', await state()); await shot('security');
await ev(`(() => { const s = document.getElementById('activity-week'); s.selectedIndex = 1; s.dispatchEvent(new Event('change', {bubbles: true})); })()`);
console.log('week 1 + security', await state());
await clickEl('input[value=failed]');
for (let i = 1; i < 4; i++) { await ev(`(() => { const s = document.getElementById('activity-week'); s.selectedIndex = ${i}; s.dispatchEvent(new Event('change', {bubbles: true})); })()`); console.log('failed + week index ' + i, await state()); }
await clickEl('input[value=all]');
await ev(`(() => { const s = document.getElementById('activity-week'); s.selectedIndex = 0; s.dispatchEvent(new Event('change', {bubbles: true})); })()`);
// Force a zero result: hide all failed rows' week by picking a week then failed; if none zero, report
const zero = await ev(`(() => { const s = document.getElementById('activity-week'); for (let i = 1; i < s.options.length; i++) { s.selectedIndex = i; document.querySelector('input[value=security]').checked = true; s.dispatchEvent(new Event('change', {bubbles: true})); if (document.getElementById('activity-table').hidden) return 'security+' + s.options[i].textContent; document.querySelector('input[value=failed]').checked = true; s.dispatchEvent(new Event('change', {bubbles: true})); if (document.getElementById('activity-table').hidden) return 'failed+' + s.options[i].textContent; } return 'no zero combo'; })()`);
console.log('zero combo', zero, await state()); await shot('empty');
if (!(JSON.parse(await state())).emptyHidden) { await clickEl('#activity-empty-clear'); console.log('click empty-state Clear filters', await state()); }
await clickEl('input[value=failed]'); await clickEl('.activity-filters__clear'); await wait(100); console.log('click bar Clear filters', await state());
// keyboard
await ev(`document.activeElement.blur(); document.querySelector('h1').setAttribute('tabindex','-1'); document.querySelector('h1').focus()`);
const ring = [];
for (let i = 0; i < 4; i++) { await key('Tab', 'Tab', 9); ring.push(await ev(`(() => { const e = document.activeElement; const c = getComputedStyle(e); return e.tagName + '[' + (e.value||e.textContent) + '] outline=' + c.outlineStyle + ' ' + c.outlineWidth + ' offset=' + c.outlineOffset; })()`)); }
console.log('tab order', ring.join(' ; '));
await ev(`document.querySelector('input[value=all]').focus()`); await key('ArrowRight', 'ArrowRight', 39); console.log('ArrowRight in radio group', await state());
console.log('target heights', await ev(`[...document.querySelectorAll('.activity-filters label, .activity-filters select, .activity-filters button')].map(e => e.tagName + ':' + Math.round(e.getBoundingClientRect().height)).join(' ')`));
await send('Emulation.setDeviceMetricsOverride', { width: 320, height: 900, deviceScaleFactor: 1, mobile: true });
await wait(300); console.log('320px scrollWidth of filters/body', await ev(`document.getElementById('activity-filters').scrollWidth + ' / form clientWidth ' + document.getElementById('activity-filters').clientWidth`)); await shot('320');
await send('Emulation.setDeviceMetricsOverride', { width: 1200, height: 900, deviceScaleFactor: 1, mobile: false });
await send('Emulation.setScriptExecutionDisabled', { value: true }); await send('Page.reload'); await wait(800);
console.log('JS disabled: form hidden?', await (async () => { const r = await send('DOM.getDocument'); const q = await send('DOM.querySelector', { nodeId: r.result.root.nodeId, selector: '#activity-filters' }); const a = await send('DOM.getAttributes', { nodeId: q.result.nodeId }); return a.result.attributes.join(' '); })()); await shot('nojs');
console.log('logs', logs.join('\n') || 'none');
ws.close(); chrome.kill();
EOF
